"""Fixed SELECT-only source contracts for approved settlement attribution."""
APPS="SELECT 'open' AS lifecycle,RTRIM(CUSTNMBR) AS customer,RTRIM(TRXSORCE) AS source,CONVERT(char(10),DATE1,120) AS apply_date,CONVERT(varchar(30),TIME1,126) AS apply_time,CONVERT(char(10),GLPOSTDT,120) AS apply_posting_date,POSTED AS posted,RTRIM(APTODCNM) AS invoice,APTODCTY AS invoice_type,CONVERT(char(10),APTODCDT,120) AS invoice_date,CONVERT(char(10),ApplyToGLPostDate,120) AS invoice_posting_date,RTRIM(APFRDCNM) AS payment,APFRDCTY AS payment_type,CONVERT(char(10),APFRDCDT,120) AS payment_date,CONVERT(char(10),ApplyFromGLPostDate,120) AS payment_posting_date,CAST(APPTOAMT AS decimal(19,2)) AS amount,CAST(DISTKNAM AS decimal(19,2)) AS discount,CAST(DISAVTKN AS decimal(19,2)) AS discount_available_taken,CAST(ActualApplyToAmount AS decimal(19,2)) AS actual_apply_amount,CAST(ActualDiscTakenAmount AS decimal(19,2)) AS actual_discount,CAST(ActualDiscAvailTaken AS decimal(19,2)) AS actual_discount_available_taken,CAST(ActualWriteOffAmount AS decimal(19,2)) AS actual_writeoff,CAST(WROFAMNT AS decimal(19,2)) AS writeoff,DEX_ROW_ID AS row_id FROM dbo.RM20201 WHERE ((GLPOSTDT>='2026-01-01' AND GLPOSTDT<'2026-11-01') OR(DATE1>='2026-01-01' AND DATE1<'2026-11-01')) AND(DISTKNAM<>0 OR ActualDiscTakenAmount<>0) UNION ALL SELECT 'history',RTRIM(CUSTNMBR) AS customer,RTRIM(TRXSORCE) AS source,CONVERT(char(10),DATE1,120) AS apply_date,CONVERT(varchar(30),TIME1,126) AS apply_time,CONVERT(char(10),GLPOSTDT,120) AS apply_posting_date,POSTED AS posted,RTRIM(APTODCNM) AS invoice,APTODCTY AS invoice_type,CONVERT(char(10),APTODCDT,120) AS invoice_date,CONVERT(char(10),ApplyToGLPostDate,120) AS invoice_posting_date,RTRIM(APFRDCNM) AS payment,APFRDCTY AS payment_type,CONVERT(char(10),APFRDCDT,120) AS payment_date,CONVERT(char(10),ApplyFromGLPostDate,120) AS payment_posting_date,CAST(APPTOAMT AS decimal(19,2)) AS amount,CAST(DISTKNAM AS decimal(19,2)) AS discount,CAST(DISAVTKN AS decimal(19,2)) AS discount_available_taken,CAST(ActualApplyToAmount AS decimal(19,2)) AS actual_apply_amount,CAST(ActualDiscTakenAmount AS decimal(19,2)) AS actual_discount,CAST(ActualDiscAvailTaken AS decimal(19,2)) AS actual_discount_available_taken,CAST(ActualWriteOffAmount AS decimal(19,2)) AS actual_writeoff,CAST(WROFAMNT AS decimal(19,2)) AS writeoff,DEX_ROW_ID AS row_id FROM dbo.RM30201 WHERE ((GLPOSTDT>='2026-01-01' AND GLPOSTDT<'2026-11-01') OR(DATE1>='2026-01-01' AND DATE1<'2026-11-01')) AND(DISTKNAM<>0 OR ActualDiscTakenAmount<>0)"
GL="WITH g AS(SELECT 'GL20000' AS source_table,OPENYEAR AS fiscal_year,JRNENTRY,DEX_ROW_ID,ACTINDX,SOURCDOC,TRXDATE,ORDOCNUM,ORTRXTYP,ORMSTRID,ORTRXSRC,DEBITAMT,CRDTAMNT FROM dbo.GL20000 WHERE Ledger_ID=1 AND VOIDED=0 AND TRXDATE>='2026-01-01' AND TRXDATE<'2026-11-01' UNION ALL SELECT 'GL30000',HSTYEAR,JRNENTRY,DEX_ROW_ID,ACTINDX,SOURCDOC,TRXDATE,ORDOCNUM,ORTRXTYP,ORMSTRID,ORTRXSRC,DEBITAMT,CRDTAMNT FROM dbo.GL30000 WHERE Ledger_ID=1 AND VOIDED=0 AND TRXDATE>='2026-01-01' AND TRXDATE<'2026-11-01') SELECT g.source_table,g.fiscal_year,g.JRNENTRY AS journal,g.DEX_ROW_ID AS row_id,RTRIM(g.SOURCDOC) AS source,CONVERT(char(10),g.TRXDATE,120) AS date,RTRIM(g.ORDOCNUM) AS payment,g.ORTRXTYP AS payment_type,RTRIM(g.ORMSTRID) AS customer,RTRIM(g.ORTRXSRC) AS origin,CAST(g.DEBITAMT-g.CRDTAMNT AS decimal(19,2)) AS cost FROM g JOIN dbo.GL00100 a ON a.ACTINDX=g.ACTINDX JOIN dbo.GL00105 n ON n.ACTINDX=g.ACTINDX WHERE n.ACTNUMST='380-00-00' AND a.ACCATNUM=32 AND UPPER(RTRIM(a.ACTDESCR))='DISCOUNTS GIVEN' ORDER BY g.JRNENTRY,g.DEX_ROW_ID"
SOP="SELECT SOPTYPE AS type,RTRIM(SOPNUMBE) AS sop,CONVERT(char(10),DOCDATE,120) AS date,RTRIM(CUSTNMBR) AS customer_id,RTRIM(CUSTNAME) AS customer,RTRIM(SLPRSNID) AS salesperson,CAST(SUBTOTAL AS decimal(19,2)) AS sales,CAST(EXTDCOST AS decimal(19,2)) AS raw_cost,VOIDSTTS AS voided,DEX_ROW_ID AS row_id,CONVERT(varchar(30),DEX_ROW_TS,126) AS row_timestamp FROM dbo.SOP30200 WHERE SOPTYPE=3 AND DOCDATE>='2026-01-01' AND DOCDATE<'2026-11-01' ORDER BY SOPNUMBE"
